from fractions import Fraction as Q
from math import factorial,comb

def moment(p,n,a):return Q(0) if n%p else Q(factorial(n),factorial(n//p))*a**(n//p)
def falling(n,r):return 0 if n<r else factorial(n)//factorial(n-r)
def mixed(p,k,l,a,t):
 if l<0:return Q(0)
 return sum(comb(l,j)*moment(p,k+j,a*t)*moment(p,l-j,a*(1-t)) for j in range(l+1))
def integrated(p,k,l,a):
 if l<0:return Q(0)
 ans=Q(0)
 for j in range(l+1):
  if (k+j)%p or (l-j)%p:continue
  A=(k+j)//p;B=(l-j)//p
  ans+=comb(l,j)*Q(factorial(k+j),factorial(A))*Q(factorial(l-j),factorial(B))*a**(A+B)*Q(factorial(A)*factorial(B),factorial(A+B+1))
 return ans
